ALTER TABLE public.website_templates ADD COLUMN IF NOT EXISTS starter_prompt text;
ALTER TABLE public.website_templates ADD COLUMN IF NOT EXISTS intake_questions jsonb NOT NULL DEFAULT '[]'::jsonb;
UPDATE public.website_templates SET starter_prompt = 'Introduce the association and point visitors to its main programs and membership.', intake_questions = '[{"id": "founded_year", "label": "What year was your association founded?", "placeholder": "1923"}, {"id": "region", "label": "What city or region do you serve?", "placeholder": "Cook County, Illinois"}, {"id": "programs", "label": "Which three programs should be featured?", "placeholder": "CLE seminars, mentorship, lawyer referral"}, {"id": "cta", "label": "What is the primary call-to-action?", "placeholder": "Join the association"}]'::jsonb WHERE is_global AND name = 'Bar Association Homepage';
UPDATE public.website_templates SET starter_prompt = 'Promote the annual convention and drive registrations.', intake_questions = '[{"id": "event_name", "label": "What is the event name?", "placeholder": "2026 Annual Convention"}, {"id": "dates", "label": "What are the dates?", "placeholder": "June 12-14, 2026"}, {"id": "venue", "label": "Where is it being held?", "placeholder": "Grand Hyatt, Nashville"}, {"id": "speakers", "label": "Who are the keynote speakers or honorees?", "placeholder": "Hon. Maria Lopez; Justice A. Chen"}, {"id": "registration_link", "label": "What is the registration link?", "placeholder": "https://example.org/register"}]'::jsonb WHERE is_global AND name = 'Annual Convention Landing Page';
UPDATE public.website_templates SET starter_prompt = 'Describe a single CLE course and get attorneys registered.', intake_questions = '[{"id": "course_title", "label": "What is the course title?", "placeholder": "Ethics in the Age of AI"}, {"id": "date_time", "label": "What is the date and time?", "placeholder": "March 4, 2026, 1:00-3:00 PM CT"}, {"id": "credits", "label": "How many credit hours, and in which state?", "placeholder": "2.0 ethics hours, Illinois MCLE"}, {"id": "instructor", "label": "Who is the instructor?", "placeholder": "Prof. Dana Whitfield"}, {"id": "takeaways", "label": "What three things will attendees learn?", "placeholder": "AI disclosure duties, confidentiality, billing"}]'::jsonb WHERE is_global AND name = 'CLE Event Page';
UPDATE public.website_templates SET starter_prompt = 'Present sponsorship tiers and invite companies to sponsor.', intake_questions = '[{"id": "tiers", "label": "What are your tier names and prices?", "placeholder": "Platinum $10,000; Gold $5,000; Silver $2,500"}, {"id": "benefits", "label": "What do sponsors receive?", "placeholder": "Logo placement, event booth, newsletter feature"}, {"id": "contact", "label": "Who should sponsors contact?", "placeholder": "Dana Reed, sponsorship@example.org"}]'::jsonb WHERE is_global AND name = 'Sponsorship Opportunities';
UPDATE public.website_templates SET starter_prompt = 'Explain the mentorship program and how to apply.', intake_questions = '[{"id": "program_name", "label": "What is the program called?", "placeholder": "Bridge the Gap Mentorship"}, {"id": "audience", "label": "Who does it serve?", "placeholder": "New admittees in their first three years"}, {"id": "matching", "label": "How does matching work?", "placeholder": "Matched by practice area and location"}, {"id": "apply", "label": "How do people apply?", "placeholder": "Apply online by March 1"}]'::jsonb WHERE is_global AND name = 'Mentorship Program';
UPDATE public.website_templates SET starter_prompt = 'Introduce a committee, its work, and how to get involved.', intake_questions = '[{"id": "committee_name", "label": "What is the committee name?", "placeholder": "Diversity & Inclusion Committee"}, {"id": "mission", "label": "What is its mission in one sentence?", "placeholder": "Advance equity across the local bar"}, {"id": "cadence", "label": "How often does it meet?", "placeholder": "Second Tuesday of each month"}, {"id": "chairs", "label": "Who chairs the committee?", "placeholder": "Alex Rivera and Priya Shah"}]'::jsonb WHERE is_global AND name = 'Committee Page';
UPDATE public.website_templates SET starter_prompt = 'Show why membership is worth it and prompt visitors to join.', intake_questions = '[{"id": "benefits", "label": "What are your top benefits?", "placeholder": "Free CLE, referral service, networking events"}, {"id": "eligibility", "label": "Who can join?", "placeholder": "Licensed attorneys and law students in the state"}, {"id": "join_link", "label": "What is the join link?", "placeholder": "https://example.org/join"}]'::jsonb WHERE is_global AND name = 'Member Benefits';
UPDATE public.website_templates SET starter_prompt = 'Let attorneys pick a membership type and join or renew.', intake_questions = '[{"id": "types", "label": "What membership types and prices do you offer?", "placeholder": "Attorney $250; New admittee $95; Student $25"}, {"id": "deadline", "label": "What is the renewal deadline?", "placeholder": "June 30 each year"}, {"id": "join_link", "label": "What is the join or renew link?", "placeholder": "https://example.org/renew"}]'::jsonb WHERE is_global AND name = 'Join / Renew Membership';
UPDATE public.website_templates SET starter_prompt = 'Point the public to local legal aid help and clinic hours.', intake_questions = '[{"id": "orgs", "label": "Which local legal aid organizations and phone numbers?", "placeholder": "Legal Aid Society, (312) 555-0111"}, {"id": "clinics", "label": "What is the clinic schedule?", "placeholder": "Walk-in clinic, Thursdays 4-7 PM"}, {"id": "eligibility", "label": "Who qualifies for help?", "placeholder": "Households under 200% of federal poverty level"}]'::jsonb WHERE is_global AND name = 'Legal Aid Resource Page';
UPDATE public.website_templates SET starter_prompt = 'Invite members to a judicial reception and collect RSVPs.', intake_questions = '[{"id": "date", "label": "What is the date and time?", "placeholder": "October 9, 2026, 6:00 PM"}, {"id": "venue", "label": "Where is the reception?", "placeholder": "City Club, 40 W Adams"}, {"id": "honorees", "label": "Who is being honored?", "placeholder": "Hon. Ruth Alvarez, retiring after 25 years"}, {"id": "rsvp", "label": "What are the RSVP details?", "placeholder": "RSVP by October 1 at events@example.org"}]'::jsonb WHERE is_global AND name = 'Judicial Reception';
UPDATE public.website_templates SET starter_prompt = 'Publish a newsletter article for members.', intake_questions = '[{"id": "topic", "label": "What is the article about?", "placeholder": "New e-filing rules taking effect"}, {"id": "author", "label": "Who is the author, and what is their title?", "placeholder": "Sam Patel, Communications Chair"}, {"id": "key_points", "label": "What are three key points?", "placeholder": "Deadline changes, fee waivers, filing portal"}]'::jsonb WHERE is_global AND name = 'Newsletter Article';
UPDATE public.website_templates SET starter_prompt = 'Feature one sponsor and send traffic to them.', intake_questions = '[{"id": "sponsor_name", "label": "What is the sponsor''s name?", "placeholder": "Meridian Court Reporting"}, {"id": "what_they_do", "label": "What do they do?", "placeholder": "Deposition and transcription services"}, {"id": "why_featured", "label": "Why are you featuring them?", "placeholder": "Five years supporting our CLE program"}, {"id": "website", "label": "What is their website?", "placeholder": "https://example.com"}]'::jsonb WHERE is_global AND name = 'Sponsor Spotlight';
UPDATE public.website_templates SET starter_prompt = 'Recruit volunteers and get them signed up.', intake_questions = '[{"id": "opportunities", "label": "What volunteer opportunities are available?", "placeholder": "Pro bono clinic, mentoring, event staffing"}, {"id": "commitment", "label": "What is the time commitment?", "placeholder": "Four hours per month"}, {"id": "signup", "label": "How do people sign up?", "placeholder": "Fill out the form or email volunteer@example.org"}]'::jsonb WHERE is_global AND name = 'Volunteer Signup';
UPDATE public.website_templates SET starter_prompt = 'Give attorneys confidential well-being resources and how to reach them.', intake_questions = '[{"id": "lap", "label": "What is your Lawyer Assistance Program name and phone number?", "placeholder": "Illinois LAP, (800) 555-0199"}, {"id": "other_resources", "label": "What other local resources should be listed?", "placeholder": "Counseling network, peer support groups"}, {"id": "cle_requirement", "label": "Is there a state wellness CLE requirement?", "placeholder": "1 mental health/substance abuse hour per cycle"}]'::jsonb WHERE is_global AND name = 'Attorney Well-Being Resources';